UPDATE user_level_progress
status = #{status, typeHandler=com.flittly.bankendspringboot.config.ProgressStatusHandler}, score = #{score}, stars = #{stars}, completion_percentage = #{completionPercentage}, completed_at = #{completedAt}, updated_at = NOW()
WHERE id = #{id, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
